//! The `veritor.reduce-mufu@1` cross-language vectors: every case of
//! `reduce_vectors.json` (generated by the predecessor implementation from its
//! Python mirror of the gates, now `verity.proofs.reduce_mufu`; frozen) evaluates to the same word
//! here, and every rejection (a MUFU table row opened at the wrong index) is
//! a rejection here.

use veritor_zk_common::gateset::{GateSet, REDUCE_MUFU_ID};

#[derive(serde::Deserialize)]
struct Vectors {
    family: String,
    digest: String,
    cases: Vec<Case>,
}

#[derive(serde::Deserialize)]
struct Case {
    op: String,
    args: Vec<String>,
    out: Option<String>,
}

#[test]
fn python_vectors_evaluate_identically() {
    let raw = include_str!("reduce_vectors.json");
    let vectors: Vectors = serde_json::from_str(raw).expect("reduce_vectors.json parses");
    assert_eq!(vectors.family, REDUCE_MUFU_ID);
    let set = GateSet::resolve(REDUCE_MUFU_ID, 32).expect("the family resolves at width 32");
    let digest: String = set.digest().iter().map(|b| format!("{b:02x}")).collect();
    assert_eq!(digest, vectors.digest, "family digest differs from the Python mirror");
    assert!(vectors.cases.len() > 10_000, "the vector file is unexpectedly small");
    for (index, case) in vectors.cases.iter().enumerate() {
        let op = set
            .op(&case.op)
            .unwrap_or_else(|| panic!("unknown gate {} (case {index})", case.op));
        let args: Vec<u64> = case
            .args
            .iter()
            .map(|hex| u64::from_str_radix(hex, 16).expect("hex argument"))
            .collect();
        let expected = case
            .out
            .as_ref()
            .map(|hex| u64::from_str_radix(hex, 16).expect("hex word"));
        let got = set.evaluate(op, &args);
        assert_eq!(
            got, expected,
            "case {index}: {}({:x?}) -> {got:x?}, python {expected:x?}",
            case.op, args
        );
    }
}
